import React, { useId } from 'react';

const STATES = new Set(['idle', 'queued', 'thinking', 'researching', 'coding', 'writing', 'working', 'waiting', 'completed', 'error', 'stopped', 'offline']);
function personality(seed) {
  let hash = 2166136261;
  for (const char of String(seed)) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return hash >>> 0;
}

/** One quiet sphere. Everything visible is clipped inside it; no accessories.
 * Presence is authoritative input, never generated by the illustration.
 * Styles are imported as text by the host, not as a side effect here.
 */
export function BotAvatar({ bot, size = 36, presence, group = false, decorative = true, interactive = false, still = false }) {
  const uid = `db-avatar-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const state = STATES.has(presence?.state) ? presence.state : 'idle';
  const color = bot?.avatar?.color || '#8B78D8';
  const name = bot?.name || (group ? 'Bot team' : 'Bot');
  const title = `${name} · ${presence?.label || state}${presence?.toolName ? ` · ${presence.toolName}` : ''}`;
  const seed = personality(bot?.id || bot?.name || 'dsh-bot');
  const pixels = Number.isFinite(Number(size)) && Number(size) > 0 ? Number(size) : 36;
  const quiet = state === 'offline' || state === 'stopped';
  return <span
    className={`dt-avatar db-avatar${group ? ' dt-avatar-group db-avatar--group' : ''}${pixels < 44 ? ' db-avatar--small' : ''}${interactive ? ' db-avatar--interactive' : ''}`}
    data-bot-state={state}
    data-bot-motion={still ? 'paused' : undefined}
    data-bot-personality={seed % 3}
    data-bot-source={presence?.source || undefined}
    data-bot-design="simple-orb"
    style={{ width: pixels, height: pixels, '--bot-color': color, '--db-avatar-phase': `${-(seed % 6700) / 1000}s`, '--db-avatar-breath': `${4.5 + (seed % 17) / 10}s`, '--db-avatar-blink': `${4.7 + (seed % 23) / 10}s` }}
    role={decorative ? undefined : 'img'}
    aria-hidden={decorative ? 'true' : undefined}
    aria-label={decorative ? undefined : title}
    title={decorative ? undefined : title}
  >
    <svg className="db-avatar__svg" viewBox={pixels < 44 ? '14 15 92 92' : '0 0 120 120'} fill="none" aria-hidden="true" focusable="false">
      {!decorative && <title>{title}</title>}
      <defs>
        <clipPath id={`${uid}-boundary`}><circle cx="60" cy="61" r="42"/></clipPath>
        <radialGradient id={`${uid}-volume`} cx=".32" cy=".26" r=".85">
          <stop stopColor="white" stopOpacity=".56"/>
          <stop offset=".36" stopColor="white" stopOpacity=".13"/>
          <stop offset=".62" stopColor="#27213E" stopOpacity="0"/>
          <stop offset="1" stopColor="#27213E" stopOpacity=".28"/>
        </radialGradient>
        <radialGradient id={`${uid}-light`} cx=".29" cy=".22" r=".63">
          <stop stopColor="white" stopOpacity=".18"/>
          <stop offset=".65" stopColor="white" stopOpacity="0"/>
          <stop offset="1" stopColor="white" stopOpacity="0"/>
        </radialGradient>
      </defs>
      <g className="db-avatar__composition">
        <g className="db-avatar__body">
          <g className="db-avatar__interior" clipPath={`url(#${uid}-boundary)`}>
            <circle className="db-avatar__sphere" cx="60" cy="61" r="42" fill={color}/>
            <circle cx="60" cy="61" r="42" fill={`url(#${uid}-volume)`}/>
            <circle cx="60" cy="61" r="42" fill={`url(#${uid}-light)`}/>
            <g className="db-avatar__face">
              {state === 'completed' ? <g className="db-avatar__happy-eyes" stroke="#302B46" strokeWidth="4" strokeLinecap="round"><path d="M41 59q5-7 10 0M69 59q5-7 10 0"/></g> : quiet ? <g stroke="#39334D" strokeWidth="3.5" strokeLinecap="round" opacity=".7"><path d="M42 60h9M69 60h9"/></g> : <g className="db-avatar__eyes"><g className="db-avatar__gaze">
                <rect className="db-avatar__eye db-avatar__eye--left" x="43" y="49" width="7.5" height="14" rx="3.75" fill="#302B46"/>
                <rect className="db-avatar__eye db-avatar__eye--right" x="69.5" y="49" width="7.5" height="14" rx="3.75" fill="#302B46"/>
                <g className="db-avatar__eye-shine" fill="white" opacity=".85"><circle cx="45.5" cy="52" r="1.2"/><circle cx="72" cy="52" r="1.2"/></g>
              </g></g>}
              {state === 'waiting' && <g className="db-avatar__brows" stroke="#39334D" strokeWidth="2.3" strokeLinecap="round"><path d="M42 43q4-3 9-2M69 41q5-1 9 2"/></g>}
              {state === 'error' && <g className="db-avatar__brows" stroke="#39334D" strokeWidth="2.3" strokeLinecap="round"><path d="m42 43 9-3m18 0 9 3"/></g>}
              {state === 'completed' ? <path className="db-avatar__mouth" d="M52 70q8 12 16 0" stroke="#302B46" strokeWidth="3" strokeLinecap="round"/> : state === 'error' ? <path className="db-avatar__mouth" d="M54 75q6-6 12 0" stroke="#302B46" strokeWidth="2.5" strokeLinecap="round"/> : quiet || state === 'queued' ? <path className="db-avatar__mouth" d="M56 73h8" stroke="#39334D" strokeWidth="2.5" strokeLinecap="round"/> : state === 'thinking' ? <ellipse className="db-avatar__mouth" cx="61" cy="72" rx="2.5" ry="2.2" fill="#302B46"/> : state === 'writing' ? <ellipse className="db-avatar__mouth" cx="60" cy="72" rx="3" ry="2" fill="#302B46"/> : <path className="db-avatar__mouth" d="M54 71q6 6 12 0" stroke="#302B46" strokeWidth="2.5" strokeLinecap="round"/>}
            </g>
          </g>
        </g>
      </g>
    </svg>
  </span>;
}

export default BotAvatar;
